-- TỰ SINH bởi scripts/supa-to-pg/compat.js — đừng sửa tay. Chạy lại được nhiều lần.
begin;
drop schema if exists qs cascade;
create schema qs;

create view qs."users" as select t."id", t."username", t."full_name" as "ho_ten", t."password_hash", t."role", t."is_active" as "active", t."created_at", t."last_login_at" as "last_login", t."permissions" as "perms", t."company_id" as "cong_ty_id", t."email", t."department" as "phong_ban", t."ui_preferences" as "ui_prefs" from public."users" t;
create view qs."cong_ty" as select t."id", t."name" as "ten", t."code" as "ma", t."logo_url", t."primary_color" as "mau_chinh", t."features" as "tinh_nang", t."user_limit" as "gioi_han_user", t."is_active" as "active", t."expiry_date" as "han_dung", t."note" as "ghi_chu", t."created_at" as "ngay_tao", t."email", t."phone" as "sdt", t."last_reminder_date" as "nhac_lan_cuoi", t."reminder_milestone" as "nhac_moc", t."has_dezon_catalog_access" as "dung_sp_dezon" from public."companies" t;
create view qs."sp_combo" as select t."id", (select p.company_id from public.products p where p.id = t.product_id) as cong_ty_id, t."product_id" as "sp_id", t."companion_product_id" as "sp_kem_id", t."quantity" as "so_luong", t."note" as "ghi_chu", t."sort_order" as "sort_no", t."created_at" from public."product_combos" t;
create view qs."sp_yeu_thich" as select t."id", t."company_id" as "cong_ty_id", t."product_id" as "sp_id", t."product_code" as "ma_sp", t."created_by" as "nguoi_tao", t."created_at" from public."favorite_products" t;
create view qs."db_san_pham_history" as select t."id", t."product_code" as "ma_sp", t."field", t."old_value", t."new_value", t."changed_by_id" as "changed_by", t."changed_by_name", t."changed_at", t."company_id" as "cong_ty_id" from public."product_histories" t;
create view qs."audit_log" as select t."id", t."user_id", t."username", t."action", t."detail", t."created_at", t."company_id" as "cong_ty_id" from public."audit_logs" t;
create view qs."notifications" as select t."id", t."user_id", t."kind", t."title", t."body", t."ref_id", t."is_read", t."created_at", t."company_id" as "cong_ty_id" from public."notifications" t;
create view qs."delete_requests" as select t."id", t."requester_id", t."requester_name", t."items", t."status", t."note", t."resolver_name", t."resolved_at", t."created_at", t."company_id" as "cong_ty_id" from public."delete_requests" t;
create view qs."du_an" as select t."id", t."project_code" as "ma_da", t."project_name" as "ten_du_an", t."customer_name" as "khach_hang", t."address" as "dia_chi", t."phone" as "sdt", t."status" as "trang_thai", t."vat_pct", t."progress_pct" as "tien_do_pct", t."note" as "ghi_chu", t."project_scale" as "quy_mo", t."total_area" as "tong_dt", t."quoted_area" as "dt_bao_gia", t."requirements" as "nhu_cau", t."segment" as "phan_khuc", t."quotation_code" as "ma_bao_gia", t."custom_groups" as "nhom_tu_tao", t."custom_floors" as "tang_tu_tao", t."created_at" as "ngay_tao", t."updated_at" as "cap_nhat", t."draft_name" as "ten_ban_nhap", t."company_id" as "cong_ty_id", t."dezon_url" as "link_dezon" from public."projects" t;
create view qs."db_bao_gia" as select t."id", t."project_code" as "ma_du_an", t."line_no" as "stt", t."zone" as "khu_vuc", t."room" as "phong", t."drawing_code" as "ma_so_ban_ve", t."product_code" as "ma_sp", t."product_name" as "ten_sp", t."brand" as "thuong_hieu", t."unit" as "dvt", t."quantity" as "so_luong", t."dealer_price" as "gia_dai_ly", t."profit_pct" as "loi_nhuan_pct", t."selling_price" as "gia_ban", t."customer_discount_pct" as "ck_khach_hang_pct", t."unit_price" as "don_gia", t."amount" as "thanh_tien", t."markup_pct", t."margin_pct", t."profit_amount" as "loi_nhuan_vnd", t."status" as "trang_thai", t."note" as "ghi_chu", t."sort_order" as "sort_no", t."created_at", t."group_code" as "nhom", t."category" as "loai", t."floor" as "tang", t."supplier_name" as "nha_cung_cap", t."description" as "mo_ta", t."size" as "kich_thuoc", t."image_urls" as "hinh_anh", t."retail_price" as "gia_ban_le", t."dealer_discount_pct" as "ck_dai_ly_pct", t."is_manual_entry" as "tu_nhap", t."is_saved_to_catalog" as "da_luu_dm", t."extra", t."supplier_discount_pct" as "giam_gia_ncc_pct", (select p.company_id from public.projects p where p.project_code = t.project_code) as cong_ty_id from public."quotation_lines" t;
create view qs."khai_toan" as select t."id", t."project_code" as "ma_da", t."item_no" as "stt", t."item_name" as "hang_muc", t."description" as "mo_ta", t."cost" as "chi_phi", t."sort_order" as "sort_no", (select p.company_id from public.projects p where p.project_code = t.project_code) as cong_ty_id from public."cost_estimate_lines" t;
create view qs."don_mua_hang" as select t."id", t."order_code" as "ma_don", t."project_code" as "ma_du_an", t."project_name" as "ten_du_an", t."category" as "hang_muc", t."supplier_name" as "nha_cung_cap", t."product_count" as "so_sp", t."subtotal_before_vat" as "tong_truoc_vat", t."vat_pct", t."vat_amount" as "vat", t."total_amount" as "tong_cong", t."status" as "trang_thai", t."send_channel" as "kenh_gui", t."send_result" as "ket_qua_gui", t."sender_name" as "nguoi_gui", t."note" as "ghi_chu", t."sent_at" as "ngay_gui", t."department" as "phong_ban", t."requester_id", t."company_id" as "cong_ty_id" from public."purchase_orders" t;
create view qs."chi_tiet_mua_hang" as select t."id", t."order_code" as "ma_don", t."product_code" as "ma_sp", t."product_name" as "ten_sp", t."brand" as "thuong_hieu", t."room" as "phong", t."unit" as "dvt", t."quantity" as "so_luong", t."unit_price" as "don_gia", t."amount" as "thanh_tien", t."image_urls" as "hinh_anh", t."sort_order" as "sort_no", (select o.company_id from public.purchase_orders o where o.order_code = t.order_code) as cong_ty_id from public."purchase_order_items" t;
create view qs."de_xuat" as select t."id", t."proposal_code" as "ma_de_xuat", t."proposal_type" as "loai", t."project_code" as "ma_du_an", t."project_name" as "ten_du_an", t."category" as "hang_muc", t."supplier_name" as "nha_cung_cap", t."line_count" as "so_dong", t."original_total" as "tong_goc", t."proposed_total" as "tong_de_xuat", t."discount_amount" as "tien_giam", t."vat_pct", t."vat_amount" as "vat", t."total_amount" as "tong_cong", t."status" as "trang_thai", t."sender_name" as "nguoi_gui", t."department" as "phong_ban", t."note" as "ghi_chu", t."resolver_name" as "nguoi_duyet", t."resolved_at" as "ngay_duyet", t."requester_id", t."company_id" as "cong_ty_id", t."sent_at" as "ngay_gui" from public."purchase_proposals" t;
create view qs."cong_tac" as select t."id", t."company_id" as "cong_ty_id", t."quotation_type" as "loai", t."calculation_mode" as "che_do", t."group_code" as "ma_nhom", t."category" as "hang_muc", t."name" as "ten", t."unit" as "dvt", t."quantity" as "khoi_luong", t."area" as "dien_tich", t."coefficient" as "he_so", t."contractor_unit_price" as "don_gia_nha_thau", t."unit_price" as "don_gia", t."note" as "ghi_chu", t."image_urls" as "hinh_anh", t."specifications" as "thong_so", t."scope" as "pham_vi", t."document_url" as "link_tai_lieu", t."is_approved" as "da_duyet", t."approved_by" as "nguoi_duyet", t."approved_at" as "ngay_duyet", t."created_by" as "nguoi_tao", t."created_at" as "ngay_tao", t."updated_by" as "nguoi_sua", t."updated_at" as "ngay_cap_nhat", t."sort_order" as "thu_tu", t."supplier_name" as "nha_cung_cap", t."is_favorite" as "yeu_thich", t."takeoff_section" as "de_muc" from public."work_items" t;
create view qs."cong_tac_history" as select t."id", t."work_item_id" as "cong_tac_id", t."field", t."old_value", t."new_value", t."changed_by_id" as "changed_by", t."changed_by_name", t."changed_at", t."company_id" as "cong_ty_id" from public."work_item_histories" t;

create view qs.db_san_pham as select p."id", p."product_code" as "ma_sp", p."product_name" as "ten_sp", p."product_line" as "dong_sp", p."category" as "hang_muc", p."product_group" as "nhom_sp", p."brand" as "thuong_hieu", p."supplier_name" as "nha_cung_cap", p."power_w" as "cong_suat_w", p."color_temperature_k" as "nhiet_do_mau_k", l."luminous_flux_lm" as "quang_thong_lm", p."beam_angle_deg" as "goc_chieu_deg", l."tilt_angle_deg" as "goc_nghieng_deg", p."color" as "mau_sac", p."material" as "chat_lieu", l."height_mm" as "chieu_cao_mm", l."diameter_mm" as "duong_kinh_mm", l."cutout_mm", p."ip_rating" as "chi_so_ip", l."cri", l."luminous_efficacy_lm_w" as "hieu_suat_lm_w", l."ugr", l."sdcm", l."coi", l."lifespan" as "tuoi_tho", l."led_chip_type" as "loai_chip_led", l."protection_class" as "class_rating", l."has_separate_driver" as "lap_nguon_roi", l."driver_name" as "ten_bo_nguon", l."driver_code" as "ma_bo_nguon", l."driver_brand" as "hang_bo_nguon", l."driver_mounting_position" as "vi_tri_lap_nguon", l."control_compatibility" as "dieu_khien", l."max_output_current_ma" as "dong_ra_max_ma", p."warranty_years" as "bao_hanh_nam", p."unit" as "dvt", p."retail_price" as "gia_ban_le", p."dealer_discount_pct" as "ck_dai_ly_pct", p."dealer_price" as "gia_dai_ly", p."image_urls" as "anh_sp", p."datasheet_url" as "link_datasheet", p."status" as "trang_thai", p."note" as "ghi_chu", p."updated_at" as "ngay_cap_nhat", p."company_id" as "cong_ty_id", p."is_approved" as "da_duyet", p."approved_by" as "nguoi_duyet", p."approved_at" as "ngay_duyet", p."created_by" as "nguoi_tao", p."created_at" as "ngay_tao", p."updated_by" as "nguoi_sua", l."led_chip_name" as "ten_chip_led", l."driver_price" as "gia_ban_bo_nguon", p."variant_group" as "nhom_bt", p."sector" as "nganh", p."size" as "kich_thuoc", v."flush_system" as "he_thong_xa", v."flush_volume" as "luong_nuoc_xa", v."design" as "thiet_ke", v."rough_in_distance" as "tam_xa", v."water_pressure" as "ap_luc_nuoc", p."caution" as "luu_y", p."features" as "tinh_nang", p."installation_type" as "kieu_lap_dat", v."lid_type" as "loai_nap", v."faucet_type" as "loai_voi", v."shower_type" as "loai_sen", v."control_type" as "kieu_dieu_khien", v."massage_function" as "massage", v."bowl_count" as "so_ho", v."flow_rate" as "luu_luong", v."valve_cartridge" as "loi_van", v."shower_head_size" as "bat_sen", v."spray_modes" as "che_do_phun", v."faucet_hole_count" as "so_lo_voi", v."overflow_hole" as "xa_tran", v."capacity" as "dung_tich", v."power_supply" as "nguon_dien", v."compatible_toilet" as "bon_cau_tuong_thich", v."thickness" as "do_day", p."surface_finish" as "be_mat", p."spec_sheet_url" as "thong_so_file", p."installation_guide_url" as "huong_dan_lap_dat", p."drawing_file_url" as "file_ban_ve", n."coverage" as "do_phu", n."drying_time" as "thoi_gian_kho", n."coat_count" as "so_lop", n."physical_state" as "trang_thai_vat_ly", n."odor" as "mui", n."odor_threshold" as "nguong_mui", n."ph_value" as "do_ph", n."melting_freezing_point" as "diem_dong", n."boiling_point" as "diem_soi", n."flash_point" as "diem_bung_chay", n."flammability" as "kha_nang_chay", n."explosive_limits" as "gioi_han_no", n."vapor_pressure" as "ap_suat_hoa_hoi", n."vapor_density" as "mat_do_hoi", n."water_solubility" as "do_hoa_tan", n."viscosity" as "tinh_deo", n."particle_characteristics" as "dac_tinh_hat", n."relative_density" as "mat_do_tuong_doi", c."component_type" as "thanh_phan", c."socket_count" as "so_o_cam", c."plug_type" as "kieu_chau", c."gang_count" as "so_nut", c."circuit_type" as "kieu_mach", c."operation_type" as "kieu_thao_tac", c."indicator_light" as "den_bao", c."safety_shutter" as "man_che", c."pack_quantity" as "quy_cach", c."rated_current_a" as "dong_dm_a", c."rated_voltage_v" as "dien_ap_v", c."max_power_w" as "cong_suat_max_w", c."max_load_power_w" as "cong_suat_tai_max_w", c."min_load_power_w" as "cong_suat_tai_min_w", c."load_type" as "loai_tai", c."operation_cycles" as "tuoi_tho_lan", c."frequency_hz" as "tan_so_hz", c."contact_material" as "vat_lieu_tiep_diem", c."flame_resistance" as "chong_chay", c."standards" as "tieu_chuan", c."certifications" as "chung_nhan", c."usb_a_port_count" as "so_usb_a", c."usb_c_port_count" as "so_usb_c", c."usb_charging_power_w" as "cong_suat_sac_w", c."usb_output" as "usb_ra", c."signal_connector_type" as "loai_tin_hieu", c."smart_integration" as "thong_minh", c."connectivity_protocol" as "giao_thuc", c."compatible_ecosystem" as "he_sinh_thai", c."neutral_wire" as "day_trung_tinh", c."sensor_type" as "loai_cam_bien", c."smart_features" as "tinh_nang_tm", c."module_count" as "so_module", c."face_width_mm" as "rong_mm", c."face_height_mm" as "cao_mm", c."face_depth_mm" as "sau_mm", c."mounting_box_type" as "loai_de", c."min_box_depth_mm" as "sau_hop_am_mm", c."max_wire_cross_section" as "tiet_dien_day", h."unit_type" as "loai_may", h."cooling_capacity_kw" as "cs_lanh_kw", h."capacity_hp" as "cs_hp", h."capacity_btu" as "cs_btu", h."operation_mode" as "che_do_van_hanh", h."compressor_type" as "may_nen", h."refrigerant" as "moi_chat_lanh", h."power_supply" as "dien_nguon_dl", h."origin_country" as "xuat_xu", h."power_input_kw" as "cs_dien_kw", h."energy_efficiency" as "hieu_suat_nl", h."energy_label" as "nhan_nang_luong", h."airflow_m3h" as "luu_luong_gio", h."indoor_noise_db" as "do_on_dan_lanh", h."outdoor_noise_db" as "do_on_dan_nong", h."cooling_area" as "pham_vi_lam_lanh", h."air_filtration" as "loc_khi", h."control_type" as "dk_dieu_hoa", h."liquid_pipe" as "ong_long", h."gas_pipe" as "ong_hoi", h."max_pipe_length_m" as "ong_dai_max", h."max_height_diff_m" as "chenh_cao_max", h."drain_pipe" as "ong_thoat_nuoc", h."power_cable" as "day_nguon", h."control_cable" as "day_dieu_khien", h."panel_model" as "mat_na", h."max_indoor_units" as "so_dan_lanh_max", h."refrigerant_charge" as "gas_nap", h."indoor_unit_dimensions" as "kt_dan_lanh", h."indoor_unit_weight_kg" as "kl_dan_lanh", h."outdoor_unit_dimensions" as "kt_dan_nong", h."outdoor_unit_weight_kg" as "kl_dan_nong", h."panel_cutout_size" as "kt_mat_na", h."installation_location" as "vi_tri_lap_dat", h."outdoor_bracket" as "gia_do_dan_nong", h."min_clearance" as "kc_lap_min", h."installation_note" as "gc_lap_dat", h."material_spec" as "quy_cach_vt" from public.products p left join public.product_lighting_specs l on l.product_id = p.id left join public.product_paint_specs n on n.product_id = p.id left join public.product_sanitary_specs v on v.product_id = p.id left join public.product_switch_socket_specs c on c.product_id = p.id left join public.product_hvac_specs h on h.product_id = p.id;
create function qs.db_san_pham_ghi() returns trigger language plpgsql as $f$
declare vid bigint;
begin
  if TG_OP = 'DELETE' then delete from public.products where id = OLD.id; return OLD; end if;
  if TG_OP = 'INSERT' then
    insert into public.products (id, "product_code", "product_name", "product_line", "category", "product_group", "brand", "supplier_name", "power_w", "color_temperature_k", "beam_angle_deg", "color", "material", "ip_rating", "warranty_years", "unit", "retail_price", "dealer_discount_pct", "image_urls", "datasheet_url", "status", "note", "updated_at", "company_id", "is_approved", "approved_by", "approved_at", "created_by", "created_at", "updated_by", "variant_group", "sector", "size", "caution", "features", "installation_type", "surface_finish", "spec_sheet_url", "installation_guide_url", "drawing_file_url") values (NEW.id, NEW."ma_sp", NEW."ten_sp", NEW."dong_sp", NEW."hang_muc", NEW."nhom_sp", NEW."thuong_hieu", NEW."nha_cung_cap", NEW."cong_suat_w", NEW."nhiet_do_mau_k", NEW."goc_chieu_deg", NEW."mau_sac", NEW."chat_lieu", NEW."chi_so_ip", NEW."bao_hanh_nam", NEW."dvt", NEW."gia_ban_le", NEW."ck_dai_ly_pct", NEW."anh_sp", NEW."link_datasheet", NEW."trang_thai", NEW."ghi_chu", NEW."ngay_cap_nhat", NEW."cong_ty_id", NEW."da_duyet", NEW."nguoi_duyet", NEW."ngay_duyet", NEW."nguoi_tao", NEW."ngay_tao", NEW."nguoi_sua", NEW."nhom_bt", NEW."nganh", NEW."kich_thuoc", NEW."luu_y", NEW."tinh_nang", NEW."kieu_lap_dat", NEW."be_mat", NEW."thong_so_file", NEW."huong_dan_lap_dat", NEW."file_ban_ve") returning id into vid;
  else
    update public.products set ("product_code", "product_name", "product_line", "category", "product_group", "brand", "supplier_name", "power_w", "color_temperature_k", "beam_angle_deg", "color", "material", "ip_rating", "warranty_years", "unit", "retail_price", "dealer_discount_pct", "image_urls", "datasheet_url", "status", "note", "updated_at", "company_id", "is_approved", "approved_by", "approved_at", "created_by", "created_at", "updated_by", "variant_group", "sector", "size", "caution", "features", "installation_type", "surface_finish", "spec_sheet_url", "installation_guide_url", "drawing_file_url") = row(NEW."ma_sp", NEW."ten_sp", NEW."dong_sp", NEW."hang_muc", NEW."nhom_sp", NEW."thuong_hieu", NEW."nha_cung_cap", NEW."cong_suat_w", NEW."nhiet_do_mau_k", NEW."goc_chieu_deg", NEW."mau_sac", NEW."chat_lieu", NEW."chi_so_ip", NEW."bao_hanh_nam", NEW."dvt", NEW."gia_ban_le", NEW."ck_dai_ly_pct", NEW."anh_sp", NEW."link_datasheet", NEW."trang_thai", NEW."ghi_chu", NEW."ngay_cap_nhat", NEW."cong_ty_id", NEW."da_duyet", NEW."nguoi_duyet", NEW."ngay_duyet", NEW."nguoi_tao", NEW."ngay_tao", NEW."nguoi_sua", NEW."nhom_bt", NEW."nganh", NEW."kich_thuoc", NEW."luu_y", NEW."tinh_nang", NEW."kieu_lap_dat", NEW."be_mat", NEW."thong_so_file", NEW."huong_dan_lap_dat", NEW."file_ban_ve") where id = OLD.id;
    vid := OLD.id;
  end if;
  if concat(NEW."quang_thong_lm", NEW."goc_nghieng_deg", NEW."chieu_cao_mm", NEW."duong_kinh_mm", NEW."cutout_mm", NEW."cri", NEW."hieu_suat_lm_w", NEW."ugr", NEW."sdcm", NEW."tuoi_tho", NEW."loai_chip_led", NEW."class_rating", NEW."lap_nguon_roi", NEW."ten_bo_nguon", NEW."ma_bo_nguon", NEW."hang_bo_nguon", NEW."vi_tri_lap_nguon", NEW."dieu_khien", NEW."dong_ra_max_ma", NEW."ten_chip_led", NEW."gia_ban_bo_nguon", NEW."coi") <> '' then
    insert into public.product_lighting_specs (product_id, "luminous_flux_lm", "tilt_angle_deg", "height_mm", "diameter_mm", "cutout_mm", "cri", "luminous_efficacy_lm_w", "ugr", "sdcm", "lifespan", "led_chip_type", "protection_class", "has_separate_driver", "driver_name", "driver_code", "driver_brand", "driver_mounting_position", "control_compatibility", "max_output_current_ma", "led_chip_name", "driver_price", "coi") values (vid, NEW."quang_thong_lm", NEW."goc_nghieng_deg", NEW."chieu_cao_mm", NEW."duong_kinh_mm", NEW."cutout_mm", NEW."cri", NEW."hieu_suat_lm_w", NEW."ugr", NEW."sdcm", NEW."tuoi_tho", NEW."loai_chip_led", NEW."class_rating", NEW."lap_nguon_roi", NEW."ten_bo_nguon", NEW."ma_bo_nguon", NEW."hang_bo_nguon", NEW."vi_tri_lap_nguon", NEW."dieu_khien", NEW."dong_ra_max_ma", NEW."ten_chip_led", NEW."gia_ban_bo_nguon", NEW."coi")
      on conflict (product_id) do update set ("luminous_flux_lm", "tilt_angle_deg", "height_mm", "diameter_mm", "cutout_mm", "cri", "luminous_efficacy_lm_w", "ugr", "sdcm", "lifespan", "led_chip_type", "protection_class", "has_separate_driver", "driver_name", "driver_code", "driver_brand", "driver_mounting_position", "control_compatibility", "max_output_current_ma", "led_chip_name", "driver_price", "coi") = row(excluded."luminous_flux_lm", excluded."tilt_angle_deg", excluded."height_mm", excluded."diameter_mm", excluded."cutout_mm", excluded."cri", excluded."luminous_efficacy_lm_w", excluded."ugr", excluded."sdcm", excluded."lifespan", excluded."led_chip_type", excluded."protection_class", excluded."has_separate_driver", excluded."driver_name", excluded."driver_code", excluded."driver_brand", excluded."driver_mounting_position", excluded."control_compatibility", excluded."max_output_current_ma", excluded."led_chip_name", excluded."driver_price", excluded."coi");
  else delete from public.product_lighting_specs where product_id = vid; end if;
